# Shared drawing kit for RIPPLE's in-game branding: the F.A.L.C.O.N. house colours, fonts, paper
# and print textures, the seal, safety-sign shapes and pictograms. Every image is drawn at twice
# its final size and shrunk on save, for smooth edges.
#
# Nothing here is generated by an AI model: shapes and text are drawn by code, and the only
# pictures pasted in are public-domain or CC0 (the falcon engraving and road-sign people from
# Openclipart, via ../falcon_tape/assets) and the Wader's silhouettes rendered from the game's own
# creature model. Fonts are SIL OFL (fonts/, with their licences) or system Liberation / Inter (OFL).
import math, os, sys
from functools import lru_cache
import numpy as np
from PIL import Image, ImageDraw, ImageFilter, ImageFont, ImageChops

HERE = os.path.dirname(os.path.abspath(__file__))
TAPE = os.path.join(HERE, "..", "falcon_tape")
sys.path.insert(0, TAPE)
import gfx  # noqa: E402  (the tape's seal and silhouettes)

SS = 2  # supersampling

# House colours (from the tape label)
NAVY = (18, 32, 92)
GOLD = (236, 196, 70)
CREAM = (233, 228, 212)
RED = (178, 30, 36)
INK = (24, 26, 34)
WHITE = (250, 248, 240)
YELLOW = (246, 189, 22)
GREEN = (0, 122, 78)

SYS = "/usr/share/fonts/truetype"
FONTS = {
    "sans": f"{SYS}/liberation/LiberationSans-Bold.ttf",
    "sansr": f"{SYS}/liberation/LiberationSans-Regular.ttf",
    "serif": f"{SYS}/liberation/LiberationSerif-Bold.ttf",
    "serifr": f"{SYS}/liberation/LiberationSerif-Regular.ttf",
    "serifi": f"{SYS}/liberation/LiberationSerif-Italic.ttf",
    "mono": f"{SYS}/freefont/FreeMonoBold.ttf",
    "black": "/usr/share/fonts/opentype/inter/Inter-Black.otf",
    "soda": f"{HERE}/fonts/TitanOne-Regular.ttf",
    "script": f"{HERE}/fonts/Pacifico-Regular.ttf",
    "fat": f"{HERE}/fonts/AbrilFatface-Regular.ttf",
    "hand1": f"{HERE}/fonts/ReenieBeanie.ttf",
    "hand2": f"{HERE}/fonts/NothingYouCouldDo.ttf",
    "hand3": f"{HERE}/fonts/ShadowsIntoLight.ttf",
    "hand4": f"{HERE}/fonts/Kalam-Regular.ttf",
    "stencil": f"{HERE}/fonts/StardosStencil-Bold.ttf",
    "slab": f"{HERE}/fonts/AlfaSlabOne-Regular.ttf",
    "neon": f"{HERE}/fonts/Sacramento-Regular.ttf",
}


def _find_inter():
    import glob
    for p in glob.glob("/usr/share/fonts/**/Inter*Black*.[ot]tf", recursive=True) + \
             glob.glob("/usr/share/fonts/**/Inter*.[ot]tf", recursive=True):
        if "Black" in p and "Italic" not in p and "Display" not in p:
            return p
    return FONTS["sans"]


if not os.path.exists(FONTS["black"]):
    FONTS["black"] = _find_inter()


@lru_cache(maxsize=None)
def F(name, size):
    """A font at `size` final pixels (scaled for the supersampled canvas)."""
    return ImageFont.truetype(FONTS[name], max(1, int(round(size * SS))))


# ---------------------------------------------------------------- canvas
def new(w, h, bg=(0, 0, 0, 0)):
    """A canvas for a w x h final image (drawn at SS times that). Returns (image, draw)."""
    if len(bg) == 3:
        bg = bg + (255,)
    im = Image.new("RGBA", (w * SS, h * SS), bg)
    return im, ImageDraw.Draw(im)


def finish(im, w, h, opaque=True):
    out = im.resize((w, h), Image.LANCZOS)
    if opaque:
        bg = Image.new("RGBA", out.size, (0, 0, 0, 255))
        bg.alpha_composite(out)
        out = bg.convert("RGB")
    return out


def P(*v):
    """Final-pixel coordinates to canvas coordinates."""
    return [x * SS for x in v] if len(v) > 1 else v[0] * SS


def text_w(s, fnt, track=0):
    return sum(fnt.getlength(ch) for ch in s) + track * SS * max(0, len(s) - 1) if track else fnt.getlength(s)


def _translucent(fill):
    return isinstance(fill, tuple) and len(fill) == 4 and fill[3] < 255


def _on_layer(d, fn):
    """Draw something translucent on a layer and composite it (ImageDraw would overwrite alpha)."""
    img = d._image
    lay = Image.new("RGBA", img.size, (0, 0, 0, 0))
    fn(ImageDraw.Draw(lay))
    img.alpha_composite(lay)


def tracked(d, x, y, s, fnt, fill, track=0, anchor="m", stroke=0, stroke_fill=None):
    """Letter-spaced text. x, y in final pixels; anchor l, m or r on x; y is the text's middle."""
    if _translucent(fill) or _translucent(stroke_fill):
        res = []
        _on_layer(d, lambda dd: res.append(_tracked(dd, x, y, s, fnt, fill, track, anchor, stroke, stroke_fill)))
        return res[0]
    return _tracked(d, x, y, s, fnt, fill, track, anchor, stroke, stroke_fill)


def _tracked(d, x, y, s, fnt, fill, track=0, anchor="m", stroke=0, stroke_fill=None):
    x, y = x * SS, y * SS
    if not track:
        a = {"l": "lm", "m": "mm", "r": "rm"}[anchor]
        d.text((x, y), s, font=fnt, fill=fill, anchor=a, stroke_width=int(stroke * SS), stroke_fill=stroke_fill)
        return fnt.getlength(s) / SS
    t = track * SS
    widths = [fnt.getlength(ch) + t for ch in s]
    total = sum(widths) - t
    cx = x - {"l": 0, "m": total / 2, "r": total}[anchor]
    for ch, w in zip(s, widths):
        d.text((cx, y), ch, font=fnt, fill=fill, anchor="lm", stroke_width=int(stroke * SS), stroke_fill=stroke_fill)
        cx += w
    return total / SS


def fit(name, s, max_w, size, track=0, min_size=6):
    """The largest font no bigger than `size` that fits `s` in max_w final pixels."""
    while size > min_size:
        fnt = F(name, size)
        if text_w(s, fnt, track) / SS <= max_w:
            return fnt
        size -= 1
    return F(name, min_size)


def para(d, x, y, s, fnt, fill, max_w, lh=1.3, anchor="l", track=0):
    """Word-wrapped text from (x, y) (top of the first line). Returns the y below it."""
    words, lines, cur = s.split(), [], ""
    for wd in words:
        t = (cur + " " + wd).strip()
        if text_w(t, fnt, track) / SS > max_w and cur:
            lines.append(cur)
            cur = wd
        else:
            cur = t
    if cur:
        lines.append(cur)
    step = fnt.size / SS * lh
    for i, ln in enumerate(lines):
        tracked(d, x, y + step * (i + 0.5), ln, fnt, fill, track, anchor)
    return y + step * len(lines)


def rect(d, x0, y0, x1, y1, fill=None, outline=None, width=0, r=0):
    if _translucent(fill) or _translucent(outline):
        return _on_layer(d, lambda dd: _rect(dd, x0, y0, x1, y1, fill, outline, width, r))
    return _rect(d, x0, y0, x1, y1, fill, outline, width, r)


def _rect(d, x0, y0, x1, y1, fill=None, outline=None, width=0, r=0):
    box = [x0 * SS, y0 * SS, x1 * SS, y1 * SS]
    if r:
        d.rounded_rectangle(box, r * SS, fill=fill, outline=outline, width=int(width * SS))
    else:
        d.rectangle(box, fill=fill, outline=outline, width=int(width * SS))


def ellipse(d, cx, cy, rx, ry=None, fill=None, outline=None, width=0):
    ry = rx if ry is None else ry
    if _translucent(fill) or _translucent(outline):
        return _on_layer(d, lambda dd: dd.ellipse([(cx - rx) * SS, (cy - ry) * SS, (cx + rx) * SS, (cy + ry) * SS],
                                                  fill=fill, outline=outline, width=int(width * SS)))
    d.ellipse([(cx - rx) * SS, (cy - ry) * SS, (cx + rx) * SS, (cy + ry) * SS], fill=fill, outline=outline,
              width=int(width * SS))


def poly(d, pts, fill=None, outline=None, width=0):
    if _translucent(fill) or _translucent(outline):
        return _on_layer(d, lambda dd: dd.polygon([(x * SS, y * SS) for x, y in pts], fill=fill, outline=outline,
                                                  width=int(width * SS)))
    d.polygon([(x * SS, y * SS) for x, y in pts], fill=fill, outline=outline, width=int(width * SS))


def line(d, pts, fill, width=1, curve=True):
    if _translucent(fill):
        return _on_layer(d, lambda dd: dd.line([(x * SS, y * SS) for x, y in pts], fill=fill, width=int(width * SS),
                                               joint="curve" if curve else None))
    d.line([(x * SS, y * SS) for x, y in pts], fill=fill, width=int(width * SS), joint="curve" if curve else None)


def paste(im, src, x, y, anchor="mm"):
    """Alpha-composite src (already canvas-sized) with its anchor at final (x, y)."""
    w, h = src.size
    ox = {"l": 0, "m": w / 2, "r": w}[anchor[0]]
    oy = {"t": 0, "m": h / 2, "b": h}[anchor[1]]
    im.alpha_composite(src, (int(x * SS - ox), int(y * SS - oy)))


def tint(mask, color, alpha=1.0):
    """An RGBA image of one colour, shaped by an L mask."""
    out = Image.new("RGBA", mask.size, tuple(color[:3]) + (255,))
    a = mask if alpha >= 1 else mask.point(lambda v: int(v * alpha))
    out.putalpha(a)
    return out


def text_mask(s, fnt, track=0, pad=0.2):
    """A tight L mask of a line of text (canvas scale)."""
    w = int(text_w(s, fnt, track) + fnt.size * 2 * pad + 4)
    h = int(fnt.size * (1.6 + 2 * pad))
    m = Image.new("L", (w, h), 0)
    dd = ImageDraw.Draw(m)
    x = fnt.size * pad
    if track:
        for ch in s:
            dd.text((x, h / 2), ch, font=fnt, fill=255, anchor="lm")
            x += fnt.getlength(ch) + track * SS
    else:
        dd.text((x, h / 2), s, font=fnt, fill=255, anchor="lm")
    return m.crop(m.getbbox())


def grow(mask, px):
    """Grow a mask by about px canvas pixels with a smooth round edge (blur, then threshold low).
    Returns the grown mask, padded by `pad` on every side, and pad."""
    pad = int(px) + 4
    m = Image.new("L", (mask.size[0] + 2 * pad, mask.size[1] + 2 * pad), 0)
    m.paste(mask, (pad, pad))
    if px <= 0:
        return m, pad
    b = m.filter(ImageFilter.GaussianBlur(px * 0.55))
    return b.point(lambda v: max(0, min(255, (v - 6) * 14))), pad


# ---------------------------------------------------------------- textures
def noise(w, h, seed, sigma=1.0, scale=1):
    rng = np.random.default_rng(seed)
    n = rng.normal(0, 1, (max(1, h // scale), max(1, w // scale)))
    if scale > 1:
        n = np.asarray(Image.fromarray(((n * 40) + 128).clip(0, 255).astype(np.uint8)).resize((w, h), Image.BICUBIC),
                       float) / 40 - 3.2
    if sigma:
        n = np.asarray(Image.fromarray(((n * 30) + 128).clip(0, 255).astype(np.uint8)).filter(
            ImageFilter.GaussianBlur(sigma)), float) / 30 - 128 / 30
    return n


def paper(w, h, seed=1, color=CREAM, grain=3.5, age=1.0):
    """Printed stock (final size w x h, returned at canvas size): grain, a little blotching and
    edges yellowed with age."""
    W, H = w * SS, h * SS
    rng = np.random.default_rng(seed)
    base = np.ones((H, W, 3)) * np.array(color, float)
    base += rng.normal(0, grain, (H, W, 1))
    base += noise(W, H, seed + 1, 0, 24)[..., None] * 2.2 * age
    yy, xx = np.mgrid[0:H, 0:W]
    edge = np.minimum(np.minimum(xx, W - 1 - xx), np.minimum(yy, H - 1 - yy)) / (0.12 * min(W, H))
    base -= np.clip(1 - edge, 0, 1)[..., None] * np.array([6, 10, 22]) * age
    im = Image.fromarray(np.clip(base, 0, 255).astype(np.uint8)).convert("RGBA")
    return im, ImageDraw.Draw(im)


def photocopy(im, seed=3, amount=1.0, paper_rgb=None):
    """Make an image read like a photocopy: toner speckle, slightly uneven blacks, soft edges."""
    a = np.asarray(im.convert("RGBA"), float)
    rng = np.random.default_rng(seed)
    H, W = a.shape[:2]
    lum = a[..., :3].mean(axis=2)
    dark = np.clip((200 - lum) / 200, 0, 1)
    # uneven toner: dark areas fade a little in blotches
    blot = noise(W, H, seed, 0, 40)
    fade = np.clip(0.10 * amount * (blot + 1.2), 0, 0.35)
    a[..., :3] += (dark * fade)[..., None] * 90
    # speckle
    spk = rng.random((H, W)) < 0.00045 * amount
    spk = np.asarray(Image.fromarray((spk * 255).astype(np.uint8)).filter(ImageFilter.MaxFilter(3)), float) / 255
    a[..., :3] = a[..., :3] * (1 - spk[..., None] * 0.75) + spk[..., None] * 30 * 0.75
    out = Image.fromarray(np.clip(a, 0, 255).astype(np.uint8), "RGBA")
    return out.filter(ImageFilter.GaussianBlur(0.6 * SS / 2))


def worn(im, seed=5, amount=1.0, chip_color=None, scratches=True, region=None):
    """Enamel/paint wear: small chips and fine scratches showing what's underneath."""
    rng = np.random.default_rng(seed)
    W, H = im.size
    lay = Image.new("RGBA", im.size, (0, 0, 0, 0))
    d = ImageDraw.Draw(lay)
    cc = chip_color or (70, 66, 60)
    for _ in range(int(7 * amount)):
        x, y = rng.uniform(0, W), rng.uniform(0, H)
        # chips cluster near edges
        if rng.random() < 0.7:
            side = rng.integers(4)
            if side == 0: x = rng.uniform(0, W * 0.05)
            elif side == 1: x = W - rng.uniform(0, W * 0.05)
            elif side == 2: y = rng.uniform(0, H * 0.06)
            else: y = H - rng.uniform(0, H * 0.06)
        r = rng.uniform(1.5, 6) * SS
        pts = [(x + math.cos(t) * r * rng.uniform(0.5, 1.2), y + math.sin(t) * r * rng.uniform(0.5, 1.2))
               for t in np.linspace(0, 2 * math.pi, 9)[:-1]]
        d.polygon(pts, fill=cc + (int(230),))
    if scratches:
        for _ in range(int(26 * amount)):
            x, y = rng.uniform(0, W), rng.uniform(0, H)
            ang = rng.uniform(0, math.pi)
            ln = rng.uniform(10, 60) * SS
            d.line([(x, y), (x + math.cos(ang) * ln, y + math.sin(ang) * ln)],
                   fill=(255, 255, 255, int(rng.uniform(25, 60))), width=1)
    # grime: darker blotches
    g = noise(W, H, seed + 9, 0, 60)
    grime = np.clip((g - 0.9) * 0.07 * amount, 0, 0.1)
    a = np.asarray(im.convert("RGBA"), float)
    a[..., :3] *= (1 - grime[..., None])
    out = Image.fromarray(np.clip(a, 0, 255).astype(np.uint8), "RGBA")
    out.alpha_composite(lay)
    if im.mode == "RGBA":
        out.putalpha(ImageChops.multiply(out.getchannel("A"), im.getchannel("A")))
    return out


def screen_dots(mask, step=6, angle=45):
    """A halftone dot pattern (L) filling a mask: for that cheap-print look."""
    W, H = mask.size
    yy, xx = np.mgrid[0:H, 0:W].astype(float)
    a = math.radians(angle)
    u = (xx * math.cos(a) + yy * math.sin(a)) / (step * SS)
    v = (-xx * math.sin(a) + yy * math.cos(a)) / (step * SS)
    dd = np.hypot(u - np.round(u), v - np.round(v))
    dots = (dd < 0.32).astype(float)
    return Image.fromarray((dots * np.asarray(mask, float)).astype(np.uint8))


# ---------------------------------------------------------------- the agency
def seal(diameter):
    """The F.A.L.C.O.N. seal (RGBA, canvas scale) `diameter` final pixels across."""
    D = int(diameter * SS)
    im = gfx.seal_image(max(30, D / 2 / gfx.S * 1.0) if D < 1200 else D / 2 / gfx.S)
    return im.resize((D, D), Image.LANCZOS)


@lru_cache(maxsize=None)
def falcon_rgba():
    return Image.open(f"{TAPE}/assets/made/falcon.png").convert("RGBA")


def falcon_lines(height):
    """The falcon engraving as an L mask of its ink (canvas scale), `height` final pixels tall."""
    im = falcon_rgba()
    h = int(height * SS)
    im = im.resize((int(im.size[0] * h / im.size[1]), h), Image.LANCZOS)
    a = np.asarray(im, float)
    ink = (255 - a[..., :3].mean(axis=2)) / 255 * (a[..., 3] / 255)
    ink = np.clip((ink - 0.25) / 0.5, 0, 1)
    return Image.fromarray((ink * 255).astype(np.uint8))


def falcon_shape(height):
    """The falcon's filled outline as an L mask (canvas scale)."""
    im = falcon_rgba()
    h = int(height * SS)
    im = im.resize((int(im.size[0] * h / im.size[1]), h), Image.LANCZOS)
    m = im.getchannel("A").point(lambda v: 255 if v > 60 else 0)
    m = m.filter(ImageFilter.MaxFilter(7)).filter(ImageFilter.MinFilter(7))   # close small gaps
    filled = Image.new("L", (m.size[0] + 2, m.size[1] + 2), 0)
    filled.paste(m, (1, 1))
    ImageDraw.floodfill(filled, (0, 0), 128)                                   # outside
    m = filled.point(lambda v: 0 if v == 128 else 255).crop((1, 1, m.size[0] + 1, m.size[1] + 1))
    return m.filter(ImageFilter.GaussianBlur(0.8))


def ring_text(im, s, cx, cy, radius, size, fill, center_deg=-90, inward=True, name="sans", spacing=1.08):
    """Lettering around a circle (all in final pixels)."""
    fnt = F(name, size)
    R = radius * SS
    widths = [fnt.getlength(ch) * spacing for ch in s]
    ang = center_deg - math.degrees(sum(widths) / 2 / R) * (1 if inward else -1)
    for ch, w in zip(s, widths):
        step = math.degrees(w / R)
        mid = ang + (step / 2 if inward else -step / 2)
        a = math.radians(mid)
        g = Image.new("RGBA", (int(fnt.size * 2), int(fnt.size * 2)), (0, 0, 0, 0))
        ImageDraw.Draw(g).text((g.size[0] / 2, g.size[1] / 2), ch, font=fnt, fill=fill, anchor="mm")
        g = g.rotate(-(mid + 90) if inward else -(mid - 90), resample=Image.BICUBIC)
        im.alpha_composite(g, (int(cx * SS + math.cos(a) * R - g.size[0] / 2),
                               int(cy * SS + math.sin(a) * R - g.size[1] / 2)))
        ang += step if inward else -step


def seal_mono(diameter, color=WHITE, ring_words=True):
    """A one-colour seal (RGBA, canvas scale): rims, lettering and the falcon's engraved lines."""
    D = diameter
    im = Image.new("RGBA", (int(D * SS) + 4, int(D * SS) + 4), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    c = D / 2 + 2 / SS
    ellipse(d, c, c, D / 2, outline=color, width=D * 0.035)
    ellipse(d, c, c, D / 2 * 0.66, outline=color, width=D * 0.022)
    if ring_words:
        ring_text(im, "FEDERAL AGENCY FOR LIMINAL CLASSIFICATION", c, c, D / 2 * 0.81, D * 0.058, color, -90, True)
        ring_text(im, "& OCCULT NATURE", c, c, D / 2 * 0.81, D * 0.058, color, 90, False)
        for a in (180 - 32, 32):
            aa = math.radians(a)
            ellipse(d, c + math.cos(aa) * D / 2 * 0.81, c + math.sin(aa) * D / 2 * 0.81, D * 0.013, fill=color)
    bird = falcon_lines(D * 0.49)
    clip = Image.new("L", im.size, 0)
    ImageDraw.Draw(clip).ellipse([(c - D * 0.3) * SS, (c - D * 0.3) * SS, (c + D * 0.3) * SS, (c + D * 0.3) * SS],
                                 fill=255)
    lay = Image.new("L", im.size, 0)
    lay.paste(bird, (int(c * SS - bird.size[0] / 2), int((c + D * 0.02) * SS - bird.size[1] / 2)))
    im.alpha_composite(tint(ImageChops.multiply(lay, clip), color))
    return im


def wordmark(d, x, y, size, fill, anchor="m"):
    """F.A.L.C.O.N. in spaced bold capitals."""
    return tracked(d, x, y, "F.A.L.C.O.N.", F("sans", size), fill, size * 0.28, anchor)


# ---------------------------------------------------------------- pictograms
@lru_cache(maxsize=None)
def _person_src(kind):
    return Image.open(f"{TAPE}/assets/people/{kind}.png").convert("L")


def person(kind, height, flip=False, rot=0):
    """A road-sign person (stand, woman, walk, run, fall) as an L mask, `height` final px tall."""
    m = _person_src(kind)
    m = m.crop(m.getbbox())
    h = int(height * SS)
    m = m.resize((max(1, int(m.size[0] * h / m.size[1])), h), Image.LANCZOS)
    if flip:
        m = m.transpose(Image.FLIP_LEFT_RIGHT)
    if rot:
        m = m.rotate(rot, resample=Image.BICUBIC, expand=True)
    return m


def wader(height, kind="side_idle", frame=0, flip=False):
    """The Wader's silhouette as an L mask (canvas scale), facing left unless flipped."""
    m = gfx.sil_mask(kind, frame, int(height * SS), flip)
    return m.crop(m.getbbox())


@lru_cache(maxsize=None)
def drop_mask():
    return Image.open(f"{TAPE}/assets/made/drop.png").convert("L")


def drop(height):
    m = drop_mask()
    h = int(height * SS)
    return m.resize((max(1, int(m.size[0] * h / m.size[1])), h), Image.LANCZOS)


def put(im, mask, x, y, color, anchor="mm", alpha=1.0):
    paste(im, tint(mask, color, alpha), x, y, anchor)


def waves(d, x0, x1, y, amp, period, width, color, rows=1, gap=None, phase=0):
    gap = gap or amp * 3.2
    for r in range(rows):
        pts = [(x, y + r * gap + math.sin((x - x0) / period * 2 * math.pi + phase) * amp)
               for x in np.linspace(x0, x1, 160)]
        line(d, pts, color, width)


def prohibition(im, cx, cy, r, figure=None, fig_h=None, fig_dy=0, water_y=None, water_rows=2):
    """An ISO-style prohibition sign: white disc, black figure, red ring and slash (final px)."""
    d = ImageDraw.Draw(im)
    lay = Image.new("RGBA", im.size, (0, 0, 0, 0))
    ld = ImageDraw.Draw(lay)
    ellipse(ld, cx, cy, r, fill=(255, 255, 255, 255))
    if figure is not None:
        put(lay, figure, cx, cy + fig_dy, (0, 0, 0))
    if water_y is not None:
        rect(ld, cx - r, cy + water_y + 4, cx + r, cy + r, fill=(255, 255, 255, 255))
        waves(ld, cx - r, cx + r, cy + water_y, r * 0.04, r * 0.42, r * 0.07, (0, 0, 0, 255), water_rows,
              r * 0.15)
    clip = Image.new("L", im.size, 0)
    ellipse(ImageDraw.Draw(clip), cx, cy, r * 0.9, fill=255)
    disc = Image.new("L", im.size, 0)
    ellipse(ImageDraw.Draw(disc), cx, cy, r, fill=255)
    lay.putalpha(ImageChops.multiply(lay.getchannel("A"), disc))
    # keep figure/waves inside the ring
    a = np.asarray(lay).copy()
    inside = np.asarray(clip) > 0
    ring_zone = (np.asarray(disc) > 0) & ~inside
    a[ring_zone] = (255, 255, 255, 255)
    lay = Image.fromarray(a)
    im.alpha_composite(lay)
    ring = Image.new("L", im.size, 0)
    rd = ImageDraw.Draw(ring)
    ellipse(rd, cx, cy, r, fill=255)
    ellipse(rd, cx, cy, r * 0.8, fill=0)
    ang = math.radians(45)
    w = r * 0.08
    dx, dy = math.cos(ang) * r * 0.82, math.sin(ang) * r * 0.82
    nx, ny = -math.sin(ang) * w, math.cos(ang) * w
    poly(rd, [(cx - dx + nx, cy - dy + ny), (cx + dx + nx, cy + dy + ny), (cx + dx - nx, cy + dy - ny),
              (cx - dx - nx, cy - dy - ny)], fill=255)
    im.alpha_composite(tint(ring, (200, 16, 30)))


def triangle_pts(cx, cy, size, inset=0.0):
    """Equilateral triangle (point up) centred at (cx, cy) with side `size`."""
    h = size * math.sqrt(3) / 2
    s = size * (1 - inset)
    hh = h * (1 - inset)
    yc = cy + h / 6
    return [(cx, yc - hh * 2 / 3), (cx + s / 2, yc + hh / 3), (cx - s / 2, yc + hh / 3)]


def warning(im, cx, cy, size, figure=None, fig_dy=0, draw=None):
    """An ISO-style warning sign: yellow triangle with a black border (rounded corners)."""
    lay = Image.new("RGBA", im.size, (0, 0, 0, 0))
    ld = ImageDraw.Draw(lay)
    outer = triangle_pts(cx, cy, size)
    ld.polygon([(x * SS, y * SS) for x, y in outer], fill=(0, 0, 0, 255))
    ld.line([(x * SS, y * SS) for x, y in outer + [outer[0]]], fill=(0, 0, 0, 255), width=int(size * 0.06 * SS),
            joint="curve")
    for x, y in outer:
        ellipse(ld, x, y, size * 0.03, fill=(0, 0, 0, 255))
    inner = triangle_pts(cx, cy + size * 0.012, size, 0.2)
    inner_m = Image.new("L", im.size, 0)
    ImageDraw.Draw(inner_m).polygon([(x * SS, y * SS) for x, y in inner], fill=255)
    lay.paste(YELLOW + (255,), (0, 0), inner_m)
    fig = Image.new("RGBA", im.size, (0, 0, 0, 0))
    if figure is not None:
        put(fig, figure, cx, cy + fig_dy, (0, 0, 0))
    if draw:
        draw(fig, ImageDraw.Draw(fig))
    fig.putalpha(ImageChops.multiply(fig.getchannel("A"), inner_m))
    lay.alpha_composite(fig)
    im.alpha_composite(lay)


def mandatory(im, cx, cy, r, figure=None, fig_dy=0):
    d = ImageDraw.Draw(im)
    ellipse(d, cx, cy, r, fill=(24, 88, 170, 255))
    if figure is not None:
        put(im, figure, cx, cy + fig_dy, (255, 255, 255))


def barcode(d, x, y, w, h, seed=1, color=INK):
    rng = np.random.default_rng(seed)
    rect(d, x - 6, y - 6, x + w + 6, y + h + 16, fill=(255, 255, 255))
    xx = x
    while xx < x + w:
        bw = rng.choice([1, 1, 2, 3]) * 1.0
        if rng.random() < 0.55:
            rect(d, xx, y, xx + bw, y + h, fill=color)
        xx += bw + rng.choice([1, 1, 2])
    tracked(d, x + w / 2, y + h + 7, "0 " + " ".join(str(rng.integers(10000, 99999)) for _ in range(2)) + " 4",
            fit("mono", "0 00000 00000 0", w + 8, 9), color)


def save(img, out, name, opaque=True, w=None, h=None):
    if w is None:
        w, h = img.size[0] // SS, img.size[1] // SS
    fin = finish(img, w, h, opaque)
    fin.save(os.path.join(out, name), optimize=True)
    return fin
